dict.string:
/usr/bin/swift -F /System/Library/PrivateFrameworks - << 'EOF'
import Foundation

Bundle(path: "/System/Library/PrivateFrameworks/MonitorPanel.framework")?.load()

guard let mgrClass = NSClassFromString("MPDisplayMgr") as? NSObject.Type,
      let mgr = mgrClass.perform(NSSelectorFromString("sharedMgr"))?.takeUnretainedValue(),
      let displays = mgr.perform(NSSelectorFromString("displays"))?.takeUnretainedValue() as? [AnyObject] else {
    exit(1)
}

typealias GetB = @convention(c) (AnyObject, Selector) -> Bool
typealias SetB = @convention(c) (AnyObject, Selector, Bool) -> Void

let hasHDR = NSSelectorFromString("hasHDRModes")
let getHDR = NSSelectorFromString("preferHDRModes")
let setHDR = NSSelectorFromString("setPreferHDRModes:")

for d in displays where d.responds(to: hasHDR) && d.responds(to: getHDR) && d.responds(to: setHDR) {
    if unsafeBitCast(d.method(for: hasHDR), to: GetB.self)(d, hasHDR) {
        let cur = unsafeBitCast(d.method(for: getHDR), to: GetB.self)(d, getHDR)
        unsafeBitCast(d.method(for: setHDR), to: SetB.self)(d, setHDR, !cur)
    }
}
EOF
